    labs=[]
    while True:
        l=d[off]; off+=1
        if l==0: break
        labs.append(d[off:off+l].decode('ascii','replace')); off+=l
    return '.'.join(labs)+'.',off

def parse_q(d):
    n,off=parse_name(d,12); qt,qc=struct.unpack('!HH',d[off:off+4]); off+=4; return n,qt,qc,off

def run(args, maxq=20):
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.bind(('127.0.0.1',0)); port=s.getsockname()[1]
