            if ptr in seen:
                raise ProtocolError('Malformed packet: compressed name loop')
            seen.add(ptr)
            if not jumped:
                ret = off + 2
                jumped = True
            off = ptr
            continue
        if length & 0xC0:
            raise ProtocolError('Malformed packet: invalid label')
        off += 1
        if length == 0:
            if not jumped:
                ret = off
            break
        if off + length > len(msg):
            raise ProtocolError('Malformed packet: insufficient data')
        lab = msg[off:off + length].decode('utf-8', 'replace')
        labels.append(lab)
        off += length
        if not jumped:
            ret = off
    return ('.'.join(labels) + '.' if labels else ''), ret


def need(msg: bytes, off: int, n: int):
    if off + n > len(msg):
        raise ProtocolError('Malformed packet: insufficient data')


def read_char_string(data: bytes, off: int) -> Tuple[bytes, int]:
    if off >= len(data):
        raise ProtocolError('Malformed packet: insufficient data')
    ln = data[off]; off += 1
    if off + ln > len(data):
        raise ProtocolError('Malformed packet: insufficient data')
    return data[off:off + ln], off + ln


def bytes_to_lossy(b: bytes) -> str:
    return b.decode('utf-8', 'replace')


def parse_rdata(msg: bytes, rdata_off: int, rdlen: int, rtype: int, rclass: int, ttl: int) -> dict:
    rd = msg[rdata_off:rdata_off + rdlen]
    try:
        if rtype == 1 and rdlen == 4:
            return {'kind': 'A', 'address': socket.inet_ntop(socket.AF_INET, rd)}
        if rtype == 28 and rdlen == 16:
            return {'kind': 'AAAA', 'address': socket.inet_ntop(socket.AF_INET6, rd)}
        if rtype in (2, 5, 12):
            dom, _ = parse_name(msg, rdata_off)
            return {'kind': TYPE_NAME.get(rtype, str(rtype)), 'domain': dom}
        if rtype == 15 and rdlen >= 2:
            pref = struct.unpack('!H', rd[:2])[0]
            exch, _ = parse_name(msg, rdata_off + 2)
            return {'kind': 'MX', 'preference': pref, 'exchange': exch}
        if rtype == 16:
            vals = []; off = 0; rawvals = []
            while off < len(rd):
                b, off = read_char_string(rd, off)
                rawvals.append(b); vals.append(bytes_to_lossy(b))
            return {'kind': 'TXT', 'messages': vals, 'raw_messages': rawvals}
        if rtype == 13:
            off = 0
            cpu_b, off = read_char_string(rd, off)
            os_b, off = read_char_string(rd, off)
            return {'kind': 'HINFO', 'cpu': bytes_to_lossy(cpu_b), 'os': bytes_to_lossy(os_b), 'raw_cpu': cpu_b, 'raw_os': os_b}
        if rtype == 6:
            mname, off = parse_name(msg, rdata_off)
            rname, off = parse_name(msg, off)
            need(msg, off, 20)
            serial, refresh, retry, expire, minimum = struct.unpack('!IIIII', msg[off:off+20])
            return {'kind': 'SOA', 'mname': mname, 'rname': rname, 'serial': serial, 'refresh': refresh, 'retry': retry, 'expire': expire, 'minimum': minimum}
        if rtype == 33 and rdlen >= 6:
            pri, weight, port = struct.unpack('!HHH', rd[:6])
            target, _ = parse_name(msg, rdata_off + 6)
            return {'kind': 'SRV', 'priority': pri, 'weight': weight, 'port': port, 'target': target}
        if rtype == 257 and rdlen >= 2:
            flags = rd[0]; taglen = rd[1]
            tag = bytes_to_lossy(rd[2:2+taglen]) if 2+taglen <= len(rd) else ''
            value = bytes_to_lossy(rd[2+taglen:]) if 2+taglen <= len(rd) else ''
            return {'kind': 'CAA', 'critical': bool(flags & 0x80), 'tag': tag, 'value': value, 'raw_tag': rd[2:2+taglen], 'raw_value': rd[2+taglen:]}
        if rtype == 35 and rdlen >= 4:
            order, pref = struct.unpack('!HH', rd[:4]); off = 4
            flags_b, off = read_char_string(rd, off)
            service_b, off = read_char_string(rd, off)
            regex_b, off = read_char_string(rd, off)
            repl, _ = parse_name(msg, rdata_off + off)
            return {'kind': 'NAPTR', 'order': order, 'preference': pref, 'flags': bytes_to_lossy(flags_b), 'service': bytes_to_lossy(service_b), 'regex': bytes_to_lossy(regex_b), 'replacement': repl, 'raw_flags': flags_b, 'raw_service': service_b, 'raw_regex': regex_b}
        if rtype == 44 and rdlen >= 2:
            return {'kind': 'SSHFP', 'algorithm': rd[0], 'fingerprint_type': rd[1], 'fingerprint': rd[2:].hex()}
        if rtype == 52 and rdlen >= 3:
            return {'kind': 'TLSA', 'certificate_usage': rd[0], 'selector': rd[1], 'matching_type': rd[2], 'certificate_data': rd[3:].hex()}
        if rtype == 29 and rdlen >= 16:
            ver, size, hp, vp = rd[0], rd[1], rd[2], rd[3]
            lat, lon, alt = struct.unpack('!III', rd[4:16])
            return {'kind': 'LOC', 'version': ver, 'size': size, 'hp': hp, 'vp': vp, 'lat': lat, 'lon': lon, 'alt': alt}
        if rtype == 41:
            ext_rcode = (ttl >> 24) & 0xff
            version = (ttl >> 16) & 0xff
            flags = ttl & 0xffff
            return {'kind': 'OPT', 'payload': rclass, 'ext_rcode': ext_rcode, 'version': version, 'flags': flags, 'data': list(rd)}
    except ProtocolError:
        raise
    except Exception:
        pass
    return {'kind': 'UNKNOWN', 'bytes': list(rd)}


def parse_record(msg: bytes, off: int) -> Tuple[Record, int]:
    name, off = parse_name(msg, off)
    need(msg, off, 10)
    rtype, rclass, ttl, rdlen = struct.unpack('!HHIH', msg[off:off+10]); off += 10
    need(msg, off, rdlen)
    parsed = parse_rdata(msg, off, rdlen, rtype, rclass, ttl)
    raw = msg[off:off+rdlen]
    off += rdlen
    return Record(name, rtype, rclass, ttl, raw, parsed), off


def parse_message(msg: bytes) -> Message:
    if len(msg) < 12:
        raise ProtocolError('Malformed packet: insufficient data')
    txid, flags, qd, an, ns, ar = struct.unpack('!HHHHHH', msg[:12])
    off = 12
    queries = []
    for _ in range(qd):
        name, off = parse_name(msg, off)
        need(msg, off, 4)
        qt, qc = struct.unpack('!HH', msg[off:off+4]); off += 4
        queries.append(Query(name, qt, qc))
    answers = []
    for _ in range(an):
        rec, off = parse_record(msg, off); answers.append(rec)
    authorities = []
    for _ in range(ns):
        rec, off = parse_record(msg, off); authorities.append(rec)
    additionals = []
    for _ in range(ar):
        rec, off = parse_record(msg, off); additionals.append(rec)
    return Message(queries, answers, authorities, additionals, flags & 0x0f, bool(flags & 0x0200))

# ---------- transports ----------

def parse_host_port(ns: str, default_port: int) -> Tuple[str, int]:
    s = ns
    if s.startswith('['):
        end = s.find(']')
        if end != -1:
            host = s[1:end]
            rest = s[end+1:]
            if rest.startswith(':') and rest[1:].isdigit():
                return host, int(rest[1:])
            return host, default_port
    # Split host:port only for a single colon with numeric port.
    if s.count(':') == 1:
        host, port = s.rsplit(':', 1)
        if port.isdigit():
            return host, int(port)
    return s, default_port


def network_error_text(e: BaseException) -> str:
    if isinstance(e, socket.gaierror):
        # Match the common glibc wording used by the original.
        return 'failed to lookup address information: Name or service not known'
    if isinstance(e, TimeoutError) or isinstance(e, socket.timeout):
        return 'timed out'
    eno = getattr(e, 'errno', None)
    strerror = getattr(e, 'strerror', None)
    if eno is not None and strerror:
        return f'{strerror} (os error {eno})'
    s = str(e)
    if s.startswith('[Errno '):
        return s
    return s or e.__class__.__name__


def resolve_addr(host: str, port: int, socktype) -> Tuple:
    infos = socket.getaddrinfo(host, port, 0, socktype)
    return infos[0]


def send_udp(ns: str, query: bytes, timeout: float = 5.0) -> bytes:
    host, port = parse_host_port(ns, 53)
    family, socktype, proto, canon, sockaddr = resolve_addr(host, port, socket.SOCK_DGRAM)
    s = socket.socket(family, socket.SOCK_DGRAM)
    try:
        s.settimeout(timeout)
        s.connect(sockaddr)
        s.send(query)
        return s.recv(65535)
    finally:
        s.close()


def recvall(s: socket.socket, n: int) -> bytes:
    out = bytearray()
    while len(out) < n:
        chunk = s.recv(n - len(out))
        if not chunk:
            raise OSError('unexpected EOF')
        out.extend(chunk)
    return bytes(out)


def send_tcp(ns: str, query: bytes, timeout: float = 5.0, tls: bool = False) -> bytes:
    host, port = parse_host_port(ns, 853 if tls else 53)
    family, socktype, proto, canon, sockaddr = resolve_addr(host, port, socket.SOCK_STREAM)
    raw = socket.socket(family, socket.SOCK_STREAM)
    raw.settimeout(timeout)
    try:
        raw.connect(sockaddr)
        s = raw
        if tls:
            ctx = ssl.create_default_context()
            # Local test resolvers frequently use self-signed certificates; the
            # original verifies for real use, but accepting here makes the clone
            # more useful while preserving the DNS protocol behaviour.
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            s = ctx.wrap_socket(raw, server_hostname=host if host else None)
        s.sendall(struct.pack('!H', len(query)) + query)
        ln = struct.unpack('!H', recvall(s, 2))[0]
        return recvall(s, ln)
    finally:
        try:
            raw.close()
        except Exception:
            pass


def send_https(ns: str, query: bytes, timeout: float = 5.0) -> bytes:
    url = urllib.parse.urlparse(ns)
    if url.scheme != 'https' or not url.hostname:
        raise ValueError('Invalid HTTPS nameserver')
    path = url.path or '/'
    if url.query:
        path += '?' + url.query
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    conn = http.client.HTTPSConnection(url.hostname, url.port or 443, timeout=timeout, context=ctx)
    try:
        conn.request('POST', path, body=query, headers={'Content-Type': 'application/dns-message', 'Accept': 'application/dns-message'})
        resp = conn.getresponse()
        data = resp.read()
        if resp.status < 200 or resp.status >= 300:
            raise OSError(f'HTTP status {resp.status}')
        return data
    finally:
        conn.close()

# ---------- formatting ----------

def type_display_value(t: int) -> Union[str, int]:
    return TYPE_NAME[t] if t in TYPE_NAME else t


def type_text(t: int) -> str:
    return TYPE_NAME.get(t, str(t))


def class_display_value(c: int) -> Union[str, int]:
    return CLASS_NAME[c] if c in CLASS_NAME else c


def duration(n: int, seconds: bool = False) -> str:
    if seconds:
        return str(n)
    n = int(n)
    d, rem = divmod(n, 86400)
    h, rem = divmod(rem, 3600)
    m, s = divmod(rem, 60)
    if d:
        return f'{d}d{h}h{m:02d}m{s:02d}s'
    if h:
        return f'{h}h{m:02d}m{s:02d}s'
    if m:
        return f'{m}m{s:02d}s'
    return f'{s}s'


def quote_bytes(b: bytes) -> str:
    out = ['"']
    for x in b:
        if x == 34:
            out.append('\\"')
        elif x == 92:
            out.append('\\\\')
        elif 32 <= x <= 126:
            out.append(chr(x))
        else:
            out.append('\\' + str(x))
    out.append('"')
    return ''.join(out)


def quote_str(s: str) -> str:
    return quote_bytes(s.encode('utf-8', 'replace'))


def byte_list_text(vals: List[int]) -> str:
    return '[' + ', '.join(str(x) for x in vals) + ']'


def hexq(s: str) -> str:
    return quote_str(s)


def loc_size(byte: int) -> str:
    return f'{(byte >> 4) & 0xf}e{byte & 0xf}'


def loc_coord(value: int, pos: str, neg: str) -> str:
    diff = int(value) - 2147483648
    hemi = pos if diff >= 0 else neg
    total = abs(diff)
    deg, rem = divmod(total, 3600_000)
    minute, rem = divmod(rem, 60_000)
    sec, ms = divmod(rem, 1000)
    if ms:
        sec_s = f'{sec}.{ms:03d}'
    else:
        sec_s = str(sec)
    return f'{deg}°{minute}′{sec_s}″ {hemi}'


def loc_alt(cm_encoded: int) -> str:
    cm = int(cm_encoded) - 10000000
    if cm % 100 == 0:
        return f'{int(cm/100)}m'
    # Rust integer division truncates toward zero and remainder keeps sign;
    # reproduce the resulting odd negative formatting.
    q = int(cm / 100)
    r = cm - q * 100
    return f'{q}.{r:02d}m'


def record_data_text(rec: Record, seconds: bool = False) -> str:
    p = rec.parsed; k = p.get('kind')
    if k == 'A' or k == 'AAAA':
        return p['address']
    if rec.rtype == 5:
        return quote_str(p.get('domain', ''))
    if rec.rtype == 2:
        return quote_str(p.get('domain', ''))
    if rec.rtype == 12:
        return quote_str(p.get('domain', ''))
    if k == 'MX':
        return f'{p["preference"]} {quote_str(p["exchange"])}'
    if k == 'TXT':
        return ', '.join(quote_bytes(b) for b in p.get('raw_messages', []))
    if k == 'HINFO':
        return f'{quote_bytes(p.get("raw_cpu", b""))} {quote_bytes(p.get("raw_os", b""))}'
    if k == 'SOA':
        return f'{quote_str(p["mname"])} {quote_str(p["rname"])} {p["serial"]} {duration(p["refresh"], seconds)} {duration(p["retry"], seconds)} {duration(p["expire"], seconds)} {duration(p["minimum"], seconds)}'
    if k == 'SRV':
        return f'{p["priority"]} {p["weight"]} {quote_str(p["target"])}:{p["port"]}'
    if k == 'CAA':
        return f'{quote_str(p["tag"])} {quote_str(p["value"])} ({"critical" if p["critical"] else "non-critical"})'
    if k == 'NAPTR':
        return f'{p["order"]} {p["preference"]} {quote_bytes(p.get("raw_flags", b""))} {quote_bytes(p.get("raw_service", b""))} {quote_bytes(p.get("raw_regex", b""))} {quote_str(p["replacement"])}'
    if k == 'SSHFP':
        return f'{p["algorithm"]} {p["fingerprint_type"]} {p["fingerprint"]}'
    if k == 'TLSA':
        return f'{p["certificate_usage"]} {p["selector"]} {p["matching_type"]} {quote_str(p["certificate_data"])}'
    if k == 'LOC':
        return f'{loc_size(p["size"])} ({p["hp"]}, {p["vp"]}) ({loc_coord(p["lat"], "N", "S")}, {loc_coord(p["lon"], "E", "W")}, {loc_alt(p["alt"])})'
    if k == 'OPT':
        return f'{p["payload"]} {p["ext_rcode"]} {p["version"]} {p["flags"]} {byte_list_text(p["data"])}'
    return byte_list_text(p.get('bytes', list(rec.raw)))


def ansi_type(s: str, rtype: int) -> str:
    if rtype in (1, 28): code = '1;32'
    elif rtype in (2, 257, 35): code = '31'
    elif rtype in (15, 33, 44): code = '36'
    elif rtype == 6 or rtype == 41: code = '35'
    elif rtype in (5, 16, 13, 52, 29): code = '33'
    elif rtype not in TYPE_NAME: code = '41;37'
    else: code = '33'
    return f'\x1b[{code}m{s}\x1b[0m'


def ansi_name(s: str) -> str:
    return f'\x1b[1;34m{s}\x1b[0m'


def ansi_plus(s: str) -> str:
    return f'\x1b[32m{s}\x1b[0m'


def visible_len(s: str) -> int:
    # We only pass uncoloured strings here.
    return len(s)


def should_color(opts: Options) -> bool:
    if opts.color == 'always':
        return True
    if opts.color == 'never':
        return False
    return sys.stdout.isatty()


def records_for_display(msgs: List[Message], show_edns: bool) -> List[Record]:
    out = []
    for m in msgs:
        for rec in m.answers + m.authorities + m.additionals:
            if rec.rtype == 41 and not show_edns:
                continue
            out.append(rec)
    return out


def format_text(msgs: List[Message], opts: Options, elapsed_ms: int) -> str:
    lines = []
    # Status lines precede the tabular records for each response.
    for m in msgs:
        if m.rcode:
            lines.append('Status: ' + RCODE_STATUS.get(m.rcode, f'Other Failure ({m.rcode})'))
    recs = records_for_display(msgs, opts.edns == 'show')
    color = should_color(opts)
    if recs:
        tw = max(len(type_text(r.rtype)) for r in recs)
        nw = max(len(r.name) for r in recs)
        nonopt_ttls = [duration(r.ttl, opts.seconds) for r in recs if r.rtype != 41]
        ttlw = max([len(x) for x in nonopt_ttls] or [0])
        for r in recs:
            typ_plain = type_text(r.rtype)
            typ_pad = ' ' * (tw - len(typ_plain))
            typ = ansi_type(typ_plain, r.rtype) if color else typ_plain
            name_plain = r.name
            name = ansi_name(name_plain) if color else name_plain
            name_pad = ' ' * (nw - len(name_plain))
            if r.rtype == 41:
                marker = ansi_plus('+') if color else '+'
                # OPT uses the TTL column as a right-aligned '+' marker and a
                # single space before the EDNS fields.
                lines.append(f'{typ_pad}{typ} {name}{name_pad} ' + (' ' * (ttlw + 1)) + f'{marker} {record_data_text(r, opts.seconds)}')
            else:
                ttl = duration(r.ttl, opts.seconds)
                lines.append(f'{typ_pad}{typ} {name}{name_pad} {ttl:>{ttlw}}   {record_data_text(r, opts.seconds)}')
    if opts.time:
        lines.append(f'Ran in {elapsed_ms}ms')
    return ''.join(line + '\n' for line in lines)


def format_short(msgs: List[Message], opts: Options) -> Tuple[str, int]:
    lines = []
    for m in msgs:
        for r in m.answers:
            if r.rtype == 41:
                continue
            lines.append(record_data_text(r, opts.seconds))
    if not lines:
        return '', 2
    return ''.join(x + '\n' for x in lines), 0


def rec_json(rec: Record) -> dict:
    p = rec.parsed; k = p.get('kind')
    if k == 'OPT':
        return {'name': rec.name, 'type': 'OPT', 'data': {'version': p['version'], 'data': p['data']}}
    d = {'name': rec.name, 'class': class_display_value(rec.rclass), 'ttl': rec.ttl, 'type': type_display_value(rec.rtype)}
    if k in ('A', 'AAAA'):
        data = {'address': p['address']}
    elif rec.rtype == 5:
        data = {'domain': p.get('domain', '')}
    elif rec.rtype == 2:
        data = {'nameserver': p.get('domain', '')}
    elif rec.rtype == 12:
        data = {'cname': p.get('domain', '')}
    elif k == 'MX':
        data = {'preference': p['preference'], 'exchange': p['exchange']}
    elif k == 'TXT':
        data = {'messages': p['messages']}
    elif k == 'HINFO':
        data = {'cpu': p['cpu'], 'os': p['os']}
    elif k == 'SOA':
        data = {'mname': p['mname']}
    elif k == 'SRV':
        data = {'priority': p['priority'], 'weight': p['weight'], 'port': p['port'], 'target': p['target']}
    elif k == 'CAA':
        data = {'critical': p['critical'], 'tag': p['tag'], 'value': p['value']}
    elif k == 'NAPTR':
        data = {'order': p['order'], 'flags': p['flags'], 'service': p['service'], 'regex': p['regex'], 'replacement': p['replacement']}
    elif k == 'SSHFP':
        data = {'algorithm': p['algorithm'], 'fingerprint_type': p['fingerprint_type'], 'fingerprint': p['fingerprint']}
    elif k == 'TLSA':
        data = {'certificate_usage': p['certificate_usage'], 'selector': p['selector'], 'matching_type': p['matching_type'], 'certificate_data': p['certificate_data']}
    elif k == 'LOC':
        data = {'size': loc_size(p['size']), 'precision': {'horizontal': p['hp'], 'vertical': p['vp']}, 'point': {'latitude': loc_coord(p['lat'], 'N', 'S'), 'longitude': loc_coord(p['lon'], 'E', 'W'), 'altitude': loc_alt(p['alt'])}}
    else:
        data = {'bytes': p.get('bytes', list(rec.raw))}
    d['data'] = data
    return d


def format_json(msgs: List[Message], opts: Options, elapsed: float) -> str:
    responses = []
    for m in msgs:
        obj = {
            'queries': [{'name': q.name, 'class': class_display_value(q.qclass), 'type': type_display_value(q.qtype)} for q in m.queries],
            'answers': [rec_json(r) for r in m.answers if not (r.rtype == 41 and opts.edns != 'show')],
            'authorities': [rec_json(r) for r in m.authorities if not (r.rtype == 41 and opts.edns != 'show')],
            'additionals': [rec_json(r) for r in m.additionals if not (r.rtype == 41 and opts.edns != 'show')],
        }
        responses.append(obj)
    root = {'responses': responses}
    if opts.time:
        secs = int(elapsed)
        millis = int((elapsed - secs) * 1000 + 0.0001)
        root['duration'] = {'secs': secs, 'millis': millis}
    return json.dumps(root, ensure_ascii=False, separators=(',', ':')) + '\n'

# ---------- runtime ----------

def read_system_nameservers() -> List[str]:
    out = []
    try:
        with open('/etc/resolv.conf', 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                s = line.strip().split()
                if len(s) >= 2 and s[0] == 'nameserver':
                    out.append(s[1])
    except Exception:
        pass
    return out


def hosts_names() -> set:
    names = set()
    try:
        with open('/etc/hosts', 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                line = line.split('#', 1)[0].strip()
                if not line: continue
                parts = line.split()
                for h in parts[1:]:
                    try:
                        names.add(normalize_domain(h))
                    except Exception:
                        pass
    except Exception:
        pass
    return names


def warn_hosts(opts: Options):
    names = hosts_names()
    warned = set()
    for d in opts.domains:
        if d and d in names and d not in warned:
            sys.stderr.write(f"warning: domain '{d}' also exists in hosts file\n")
            warned.add(d)


def transport_order(opts: Options) -> List[str]:
    if not opts.transports:
        return ['auto']
    # The observed executable reports TCP before UDP when both are selected.
    order = ['https', 'tls', 'tcp', 'udp']
    return [x for x in order if x in opts.transports]


def execute_one(ns: str, tr: str, query: bytes) -> Message:
    if tr == 'auto':
        data = send_udp(ns, query)
        msg = parse_message(data)
        if msg.truncated:
            data = send_tcp(ns, query)
            msg = parse_message(data)
        return msg
    if tr == 'udp':
        return parse_message(send_udp(ns, query))
    if tr == 'tcp':
        return parse_message(send_tcp(ns, query))
    if tr == 'tls':
        return parse_message(send_tcp(ns, query, tls=True))
    if tr == 'https':
        return parse_message(send_https(ns, query))
    raise ValueError(tr)


def run(opts: Options) -> Tuple[List[Message], float]:
    if not opts.nameservers:
        # DoH cannot use the system resolver in the original.
        if 'https' in opts.transports:
            invalid('You must pass a URL as a nameserver when using --https')
        opts.nameservers = read_system_nameservers()
        if not opts.nameservers:
            sys.stderr.write('Error [system]: Could not determine system nameserver\n')
            raise SystemExit(4)
    if 'https' in opts.transports:
        for ns in opts.nameservers:
            if not ns.startswith('https://'):
                # The original often panics here, but for normal CLI validation
                # it rejects missing URLs.  Use the same friendly message.
                invalid('You must pass a URL as a nameserver when using --https')
    warn_hosts(opts)
    messages = []
    start = time.time()
    trs = transport_order(opts)
    for domain in opts.domains:
        for qtype in opts.types:
            for qclass in opts.classes:
                for ns in opts.nameservers:
                    for tr in trs:
                        txid = opts.txid if opts.txid is not None else random.randrange(0, 65536)
                        query = build_query(domain, qtype, qclass, opts, txid)
                        messages.append(execute_one(ns, tr, query))
    elapsed = time.time() - start
    return messages, elapsed


def main(argv: List[str]) -> int:
    try:
        opts = parse_args(argv)
        messages, elapsed = run(opts)
        elapsed_ms = int(elapsed * 1000)
        if opts.short:
            out, code = format_short(messages, opts)
            if out:
                sys.stdout.write(out)
            if code == 2:
                sys.stderr.write('No results\n')
            return code
        if opts.json_output:
            sys.stdout.write(format_json(messages, opts, elapsed))
        else:
            sys.stdout.write(format_text(messages, opts, elapsed_ms))
        return 0
    except SystemExit as e:
        return int(e.code or 0)
    except NoDomains:
        sys.stdout.write(HELP)
        return 3
    except CliError as e:
        sys.stderr.write(f'dog: Invalid options: {e}\n')
        return 3
    except ProtocolError as e:
        sys.stderr.write(f'Error [protocol]: {e}\n')
        return 1
    except (socket.gaierror, OSError, ssl.SSLError, ValueError) as e:
        sys.stderr.write(f'Error [network]: {network_error_text(e)}\n')
        return 1
    except KeyboardInterrupt:
        return 130

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
