    'HIP': 55, 'NINFO': 56, 'RKEY': 57, 'TALINK': 58, 'CDS': 59,
    'CDNSKEY': 60, 'OPENPGPKEY': 61, 'CSYNC': 62, 'ZONEMD': 63, 'SVCB': 64,
    'HTTPS': 65, 'URI': 256, 'CAA': 257, 'AVC': 258, 'DOA': 259,
    'AMTRELAY': 260, 'IXFR': 251, 'AXFR': 252, 'MAILB': 253, 'MAILA': 254,
